#!/usr/bin/env node
/**
 * PreToolUse guard against hand-editing generated files (AI-11).
 *
 * Denies an agent's file edit or write when the target is generated: either it
 * sits under a directory the repo lists as regenerated output, or its header
 * declares it generated or not to be edited by hand. The fix is always to change
 * the generator and regenerate, so the denial says so. Regeneration commands are
 * untouched, because the guard inspects edit tools only, never shell side effects.
 *
 * Domain-neutral: the repo's own paths live in generated-file-guard.json beside
 * this script, so another repo can reuse the script with its own config.
 *
 * Config (all optional):
 *   generatedDirectories  repo-relative directories whose whole tree is generated
 *   checkHeaders          false to skip the header check (default true)
 */
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const SCRIPT_DIRECTORY = path.dirname(fileURLToPath(import.meta.url))
const CONFIG_PATH = path.join(SCRIPT_DIRECTORY, 'generated-file-guard.json')

/** scripts/hooks/ sits two levels below the repo root, so paths never depend on the host. */
const REPOSITORY_ROOT = path.resolve(SCRIPT_DIRECTORY, '..', '..')

/** Phrases a generator writes into the files it owns. Only the first 4 KB is read. */
const GENERATED_HEADER_PATTERN = /(?:generated(?: file)?[^\n]{0,100}do not edit|generated by[^\n]{0,100}do not edit|regenerate rather than edit|do not edit this file manually)/i

/** Tools that change a file, and the input field naming it. */
const EDIT_TOOLS = {
  Edit: 'file_path',
  MultiEdit: 'file_path',
  Write: 'file_path',
  NotebookEdit: 'notebook_path'
}

/**
 * Read the repo's guard config.
 * @param {string} configPath JSON file to read; a missing file means defaults
 * @returns {{ generatedDirectories: string[], checkHeaders: boolean }}
 */
export function loadConfig(configPath = CONFIG_PATH) {
  let raw = {}
  try {
    raw = JSON.parse(readFileSync(configPath, 'utf8'))
  } catch (error) {
    if (error.code !== 'ENOENT') throw new Error(`Could not read ${configPath}: ${error.message}`)
  }

  return {
    generatedDirectories: Array.isArray(raw.generatedDirectories) ? raw.generatedDirectories : [],
    checkHeaders: raw.checkHeaders !== false
  }
}

/**
 * Whether a file's leading comment declares it generated or not to be edited.
 * A missing or unreadable file is not this guard's concern: a Write that creates
 * a new file has nothing to protect, and the tool reports its own read errors.
 */
export function hasGeneratedHeader(filePath) {
  try {
    return GENERATED_HEADER_PATTERN.test(readFileSync(filePath, 'utf8').slice(0, 4096))
  } catch {
    return false
  }
}

/**
 * Whether a path is inside one of the configured generated directories.
 * @param {string} filePath absolute path of the edit target
 * @param {string[]} directories repo-relative generated directories
 * @param {string} repositoryRoot absolute repo root the directories are relative to
 */
export function isInGeneratedDirectory(filePath, directories, repositoryRoot = REPOSITORY_ROOT) {
  const relativePath = path.relative(repositoryRoot, filePath)

  return directories.some((directory) => {
    const normalized = path.normalize(directory).replace(/[\\/]+$/, '')
    return relativePath === normalized || relativePath.startsWith(normalized + path.sep)
  })
}

/**
 * Decide one PreToolUse event.
 * @returns the hook response that denies the edit, or null to let it proceed
 */
export function evaluateEdit(event, config, repositoryRoot = REPOSITORY_ROOT) {
  if (event.hook_event_name !== 'PreToolUse') return null

  const field = EDIT_TOOLS[event.tool_name]
  const target = field ? event.tool_input?.[field] : undefined
  if (typeof target !== 'string' || target === '') return null

  const targetPath = path.resolve(event.cwd ?? repositoryRoot, target)
  const generatedDirectory = isInGeneratedDirectory(targetPath, config.generatedDirectories, repositoryRoot)
  const generatedHeader = config.checkHeaders && hasGeneratedHeader(targetPath)
  if (!generatedDirectory && !generatedHeader) return null

  const shown = path.relative(repositoryRoot, targetPath) || target
  return {
    hookSpecificOutput: {
      hookEventName: 'PreToolUse',
      permissionDecision: 'deny',
      permissionDecisionReason: `${shown} is generated. Edit the generator or its source and regenerate instead.`
    }
  }
}

/** Read the whole hook event from stdin. */
function readStdin() {
  return new Promise((resolve, reject) => {
    let input = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => { input += chunk })
    process.stdin.on('end', () => resolve(input))
    process.stdin.on('error', reject)
  })
}

/**
 * Hook entry point. The only stdout is the hook response. A failure in the guard
 * itself is reported as a message and lets the edit proceed, since a broken guard
 * should not block all editing.
 */
async function main() {
  try {
    const event = JSON.parse(await readStdin())
    const response = evaluateEdit(event, loadConfig())
    if (response) process.stdout.write(JSON.stringify(response))
  } catch (error) {
    process.stdout.write(JSON.stringify({ systemMessage: `Generated-file guard failed: ${error.message}` }))
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await main()
}
